def smooth_loop(p):
 out=[]
 for i,b in enumerate(p):
  a=p[i-1];c=p[(i+1)%len(p)];d=p[(i+2)%len(p)]
  for t in[0,.5]:out.append(tuple(.5*((2*b[k])+(-a[k]+c[k])*t+(2*a[k]-5*b[k]+4*c[k]-d[k])*t*t+(-a[k]+3*b[k]-3*c[k]+d[k])*t*t*t)for k in range(2)))
 return out
def triangulate_polygon(p):
 def cr(a,b,c):return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
 area=sum(a[0]*b[1]-a[1]*b[0]for a,b in zip(p,p[1:]+p[:1]));ids=list(range(len(p)))if area>0 else list(reversed(range(len(p))));out=[]
 while len(ids)>3:
  found=False
  for j,b in enumerate(ids):
   a=ids[j-1];c=ids[(j+1)%len(ids)]
   if cr(p[a],p[b],p[c])<=1e-13:continue
   if any(min(cr(p[a],p[b],p[v]),cr(p[b],p[c],p[v]),cr(p[c],p[a],p[v]))>=-1e-13 for v in ids if v not in[a,b,c]):continue
   out.append((a,b,c));ids.pop(j);found=True;break
  assert found,'Thallus outline is not simple'
 out.append(tuple(ids));return out
BRANCHES=[((0,-.030),(0,-.005)),((0,-.005),(-.019,.029)),((0,-.005),(.019,.030))]
def branch_distance(x,y):
 vals=[]
 for(a,b)in BRANCHES:
  dx,dy=b[0]-a[0],b[1]-a[1];t=max(0,min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));vals.append(math.hypot(x-a[0]-t*dx,y-a[1]-t*dy))
 return min(vals)
def thallus_height(x,y):return .00105+.00105*math.exp(-(branch_distance(x,y)/.004)**2)+.00010*math.sin(x*250+y*130)
